type activityDataMsg struct {
	stats  contributionStats
	repos  []repoContribution
	hourly []hourlyPoint
	days   []commitDay
}

// activityErrMsg is sent when fetching fails.
type activityErrMsg struct{ err error }

type activityModel struct {
	// Data (nil until loaded)
	stats  *contributionStats
	repos  []repoContribution
	hourly []hourlyPoint
	days   []commitDay

	// Loading state
	loading bool
