	}

	m.width = 20
	m.sty = newActivityStylesWithWidth(m.width, true)

	footer = m.renderFooter()
	if got := lipgloss.Width(footer); got != m.width {
		t.Fatalf("narrow footer width = %d, want %d: %q", got, m.width, footer)
	}
}

