    99		switch msg := msg.(type) {
   100		case activityDataMsg:
   101			m.loading = false
   102			m.stats = &msg.stats
   103			m.repos = msg.repos
   104			m.hourly = msg.hourly
   105			m.days = msg.days
   106			if m.width > 0 {
   107				m = m.withViewport()
   108			}
   109			return m, nil
   110	
   111		case activityErrMsg:
   112			m.loading = false
   113			m.loadErr = msg.err
   114			return m, nil
   115	
   116		case tea.KeyMsg:
   117			if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
   118				return m, tea.Quit
   119			}
   120			if key.Matches(msg, keys.Home) {
   121				if m.ready {
   122					m.viewport.GotoTop()
   123				}
